                            </motion.div>
                        )}
                        {status === 'submitting' && (
                            <motion.div 
                                key="submitting"
                                initial={{ y: 20, opacity: 0 }}
                                animate={{ y: 0, opacity: 1 }}
                                exit={{ y: -20, opacity: 0 }}
                                className="flex items-center gap-2"
                            >
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Sending...
                            </motion.div>
                        )}
                        {status === 'success' && (
                            <motion.div 
                                key="success"
                                initial={{ y: 20, opacity: 0 }}
                                animate={{ y: 0, opacity: 1 }}
                                className="flex items-center gap-2"
                            >
                                <Check className="w-5 h-5" />
                                Message Sent!
                            </motion.div>
                        )}
                    </AnimatePresence>
                </button>
              </div>
