    // Check session storage
    const hasVisited = sessionStorage.getItem('hasVisited');
    if (hasVisited) {
      onComplete();
      setStage('complete');
      return;
    }

    // Start sequence
    setStage('closed');
    sessionStorage.setItem('hasVisited', 'true');

    // Sequence timing
    const openTimer = setTimeout(() => setStage('opening'), 500);
    const bootTimer = setTimeout(() => setStage('booting'), 2000);

    return () => {
      clearTimeout(openTimer);
      clearTimeout(bootTimer);
    };
  }, [onComplete]);

  // Boot text effect
  useEffect(() => {
    if (stage === 'booting') {
      if (textIndex < BOOT_SEQUENCE.length) {
        const timeout = setTimeout(() => {
          setBootLog(prev => [...prev, BOOT_SEQUENCE[textIndex]]);
          setTextIndex(prev => prev + 1);
        }, 600); // Speed of log lines
        return () => clearTimeout(timeout);
      } else {
        // Finished booting, start zoom
        setTimeout(() => setStage('zooming'), 800);
      }
    }
  }, [stage, textIndex]);

  // Handle Zoom Finish
  useEffect(() => {
    if (stage === 'zooming') {
      const timer = setTimeout(() => {
        onComplete();
      }, 1500); // Wait for zoom to finish
      return () => clearTimeout(timer);
    }
  }, [stage, onComplete]);

