];

export const NavBar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll();

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Prevent body scroll when mobile menu is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
  }, [isOpen]);

  const handleLinkClick = (path: string, e?: React.MouseEvent) => {
    // Determine if it's a hash link or home
    if (path.startsWith('/#') || path === '/') {
        if (e) e.preventDefault();

        let targetId = '';
        if (path.startsWith('/#')) {
            targetId = path.replace('/#', '');
        } else {
            // Path is '/' - scroll to top
            targetId = 'top'; 
        }

        const performScroll = () => {
            if (targetId === 'top') {
                 window.scrollTo({ top: 0, behavior: 'smooth' });
            } else {
                 const element = document.getElementById(targetId);
                 if (element) {
                     const navHeight = 85; // slightly more for breathing room
                     const elementPosition = element.getBoundingClientRect().top;
                     const offsetPosition = elementPosition + window.pageYOffset - navHeight;
                     window.scrollTo({ top: offsetPosition, behavior: 'smooth' });
                 }
            }
        };

        if (location.pathname !== '/') {
            navigate('/');
            // Wait for transition (approx 600ms-800ms)
            setTimeout(performScroll, 700);
        } else {
            performScroll();
        }
        setIsOpen(false);
    } else {
        // Standard route navigation (Projects, Insights)
        window.scrollTo(0,0);
        setIsOpen(false);
    }
  };

  const handleContactClick = (e: React.MouseEvent) => {
    e.preventDefault();
    if (location.pathname !== '/') {
      navigate('/');
      setTimeout(() => {
        const element = document.getElementById('contact');
        if (element) element.scrollIntoView({ behavior: 'smooth' });
      }, 700);
    } else {
      const element = document.getElementById('contact');
      if (element) element.scrollIntoView({ behavior: 'smooth' });
    }
    setIsOpen(false);
  };

