    if (cat.includes('professional')) return <Users className="w-6 h-6 text-pink-400" />;
    if (cat.includes('communication')) return <LangIcon className="w-6 h-6 text-indigo-400" />;
    return <Code2 className="w-6 h-6 text-slate-400" />;
